/**
 * @method
 * @name scwin.unformat
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.unformat = function (obj) {
    /* sdd-asis-lifecycle:begin unformat — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let temp = "";
    const n = String(obj.value);
    const len = n.length;
    let pos = 0;
    let ch = '';
    while (pos < len) {
        ch = n.charAt(pos);
        if (((ch >= '0') && (ch <= '9')) || (ch === '-')) {
            temp = temp + ch;
        }
        pos = pos + 1;
    }
    obj.value = temp;
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.numFormat
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.numFormat = async function (obj) {
    /* sdd-asis-lifecycle:begin numFormat — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ((obj.getValue() == null ? '' : String(obj.getValue())) !== '' && !scwin.isMinusNum(obj.getValue())) {
        obj.setValue("");
        await $c.win.alert("숫자만 입력가능합니다.");
        obj.focus();
        return;
    }
    scwin.unformat(obj);
    if ((obj.getValue() == null ? '' : String(obj.getValue())) === '') {
        return;
    }
    if (isNaN(obj.getValue())) {
        obj.setValue("");
        return;
    }
    if (Number(obj.getValue()) > 999999999999999 || Number(obj.getValue()) < -999999999999999) {
        obj.setValue("");
        await $c.win.alert("입력한 숫자가 범위를 초과하였습니다.");
        obj.focus();
        return;
    }
    let str = Number(obj.getValue()) + "";
    let sMinusChar = "";
    if (Number(obj.getValue()) < 0) {
        str = str.substring(1);
        sMinusChar = "-";
    }
    let tempStr = str;
    let fltStr = "";
    if (str.indexOf(".") > -1) {
        tempStr = str.substr(0, str.indexOf("."));
        fltStr = str.substr(str.indexOf("."));
    }
    const leng = tempStr.length;
    const size = 3;
    const cnt = Math.floor(leng / size);
    const pos = leng % size;
    let result = "";
    if (cnt == 0) {
        obj.setValue(Number(obj.getValue()));
        return;
    }
    for (let i = cnt; i > 0; i = i - 1) {
        result = "," + tempStr.substr(pos + (i - 1) * size, size) + result;
    }
    if (result !== '') {
        if (pos == 0) {
            obj.setValue(sMinusChar + result.substring(1) + fltStr);
        } else {
            obj.setValue(sMinusChar + str.substr(0, pos) + result + fltStr);
        }
    }
    return;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.numFormat2
 * @author Inswave
