    /* sdd-asis-lifecycle:begin isMinusNum — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    var ch = "\0";
    let flag = true;
    ch = name.charAt(0);
    flag = ((ch >= '0' && ch <= '9') || ch === '-') ? true : false;
    for (var i = 1, ch = name.charAt(i); (i < name.length) && (flag); ch = name.charAt(++i)) {
        if ((ch >= '0') && (ch <= '9')) {

        } else {
            flag = false;
        }
    }
    return flag;
    /* sdd-asis-lifecycle:end */
};


