/**
 * @method
 * @name scwin.delRows
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowId
 * @returns
 * @hidden N
*/
scwin.delRows = async function (rowId) {
    /* sdd-asis-lifecycle:begin fn_delRows — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const divID = "rowPlus_" + rowId;
    const objNm = "row" + rowId;
    const rowPlus = $c.util.getComponent(divID);
    const rowCnt = (objNm);
    if (rowCnt > 1) {
        const no = rowPlus.rows.length - 1;
        rowPlus.deleteRow(no);
        switch (rowId) {
            case 1:
            scwin.row1--;
            break;
            case 2:
            scwin.row2--;
            break;
            case 3:
            scwin.row3--;
            break;
            case 4:
            scwin.row4--;
            break;
        }
    } else {
        if (rowCnt < 2) {
            await $c.win.alert("최소한 1줄은 작성하셔야 합니다.");
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.calculation1
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowId seqNum
 * @returns
 * @hidden N
*/
scwin.calculation1 = async function (rowId, seqNum) {
    /* sdd-asis-lifecycle:begin fn_calculation_1 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let objNm1 = "";
    if (rowId == 1) {
        objNm1 = "paidInSurplus_" + rowId + "[" + seqNum + "]";
    } else {
        if (rowId == 2) {
            objNm1 = "changeBondPrice_" + rowId + "[" + seqNum + "]";
        }
    }
    const objNm2 = "changePrice_" + rowId + "[" + seqNum + "]";
    const objNm3 = "issueShare_" + rowId + "[" + seqNum + "]";
    const objNm4 = "growCapital_" + rowId + "[" + seqNum + "]";
    if (rowId == 1) {
        if (($c.util.getComponent(objNm1).getValue() != null && $c.util.getComponent(objNm1).getValue() !== '') && ($c.util.getComponent(objNm2).getValue() != null && $c.util.getComponent(objNm2).getValue() !== '')) {
            scwin.unformat($c.util.getComponent(objNm1));
            scwin.unformat($c.util.getComponent(objNm2));
            var issueShare = $c.util.getComponent(objNm1).getValue() / $c.util.getComponent(objNm2).getValue();
            $c.util.getComponent(objNm3).setValue(Math.floor(issueShare));
            await scwin.numFormat($c.util.getComponent(objNm1));
            await scwin.numFormat($c.util.getComponent(objNm2));
            await scwin.changeParval();
        }
    } else {
        if (rowId == 2) {
            if (($c.util.getComponent(objNm1).getValue() != null && $c.util.getComponent(objNm1).getValue() !== '') && ($c.util.getComponent(objNm2).getValue() != null && $c.util.getComponent(objNm2).getValue() !== '')) {
                scwin.unformat($c.util.getComponent(objNm1));
                scwin.unformat($c.util.getComponent(objNm2));
                var issueShare = $c.util.getComponent(objNm1).getValue() / $c.util.getComponent(objNm2).getValue();
                $c.util.getComponent(objNm3).setValue(Math.floor(issueShare));
                await scwin.numFormat($c.util.getComponent(objNm1));
                await scwin.numFormat($c.util.getComponent(objNm2));
                await scwin.changeParval();
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeParval
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.changeParval = async function () {
    /* sdd-asis-lifecycle:begin changeParval — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let objNm1 = "";
    let objNm2 = "";
    const rowId = "row";
    for (let n = 1; n < 5; n++) {
        const rowCnt = rowId + n;
        for (let i = 0; i < (rowCnt); i++) {
            objNm1 = "issueShare_" + n + "[" + i + "]";
            objNm2 = "growCapital_" + n + "[" + i + "]";
            objNm3 = "paidInSurplus_" + n + "[" + i + "]";
            if (parval.value != null && parval.value !== '') {
                scwin.unformat($c.util.getComponent(objNm1));
                scwin.unformat(parval);
                const growCapital = $c.util.getComponent(objNm1).getValue() * parval.value;
                $c.util.getComponent(objNm2).setValue(growCapital);
                if (n == 1) {
                    await scwin.sumRow(1, 'paidInSurplus');
                }
                await scwin.sumRow(n, 'issueShare');
                await scwin.sumRow(n, 'growCapital');
                await scwin.numFormat(parval);
            }
        }
        switch (n) {
            case 1:
            $c.util.getComponent('ipt_capInc1').setValue($c.util.getComponent("ipt_sumGrowCapital1").getValue());
            await scwin.sumCapInc();
            break;
            case 2:
            $c.util.getComponent('ipt_capInc2').setValue($c.util.getComponent("ipt_sumGrowCapital2").getValue());
            await scwin.sumCapInc();
            break;
            case 3:
            $c.util.getComponent('ipt_capInc3').setValue($c.util.getComponent("ipt_sumGrowCapital3").getValue());
            await scwin.sumCapInc();
            break;
            case 4:
            $c.util.getComponent('ipt_freeCap').setValue($c.util.getComponent("ipt_sumGrowCapital4").getValue());
            $c.util.getComponent('ipt_sumFreeCap').setValue($c.util.getComponent("ipt_sumGrowCapital4").getValue());
            break;
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.sumRow
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowId objNm
 * @returns
 * @hidden N
*/
scwin.sumRow = async function (rowId, objNm) {
    /* sdd-asis-lifecycle:begin sumRow — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const obj = objNm + "_" + rowId;
    const rowCnt = eval("row" + rowId);
    const sumObj = "sum_" + obj;
    let sum = 0;
    for (let n = 0; n < rowCnt; n++) {
        const objVal = obj + "[" + n + "]";
        scwin.unformat($c.util.getComponent(objVal));
        scwin.unformat($c.util.getComponent(sumObj));
        if ($c.util.getComponent(objVal).value == null || $c.util.getComponent(objVal).value === "") {
            sum += 0;
        } else {
            sum += parseInt($c.util.getComponent(objVal).getValue());
        }
        await scwin.numFormat($c.util.getComponent(objVal));
    }
    $c.util.getComponent(sumObj).setValue(sum);
    await scwin.numFormat($c.util.getComponent(sumObj));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.sumCapInc
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.sumCapInc = async function () {
    /* sdd-asis-lifecycle:begin sumCapInc — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let capInc_1 = 0;
    let capInc_2 = 0;
    let capInc_3 = 0;
    scwin.unformat($c.util.getComponent("ipt_capInc1"));
    scwin.unformat($c.util.getComponent("ipt_capInc2"));
    scwin.unformat($c.util.getComponent("ipt_capInc3"));
    if (($c.util.getComponent('ipt_capInc1').getValue() == null ? '' : String($c.util.getComponent('ipt_capInc1').getValue())) !== '' && $c.util.getComponent('ipt_capInc1').getValue() != null) {
        capInc_1 = parseInt($c.util.getComponent('ipt_capInc1').getValue());
    }
    if (($c.util.getComponent('ipt_capInc2').getValue() == null ? '' : String($c.util.getComponent('ipt_capInc2').getValue())) !== '' && $c.util.getComponent('ipt_capInc2').getValue() != null) {
        capInc_2 = parseInt($c.util.getComponent('ipt_capInc2').getValue());
    }
    if (($c.util.getComponent('ipt_capInc3').getValue() == null ? '' : String($c.util.getComponent('ipt_capInc3').getValue())) !== '' && $c.util.getComponent('ipt_capInc3').getValue() != null) {
        capInc_3 = parseInt($c.util.getComponent('ipt_capInc3').getValue());
    }
    const sum = capInc_1 + capInc_2 + capInc_3;
    $c.util.getComponent('ipt_sumCapInc').setValue(sum);
    await scwin.numFormat($c.util.getComponent("ipt_capInc1"));
    await scwin.numFormat($c.util.getComponent("ipt_capInc2"));
    await scwin.numFormat($c.util.getComponent("ipt_capInc3"));
    await scwin.numFormat($c.util.getComponent("ipt_sumCapInc"));
    await scwin.safeGuardDeposit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.safeGuardDeposit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.safeGuardDeposit = async function () {
    /* sdd-asis-lifecycle:begin fn_safeGuardDeposit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let capital = 0;
    let parval = 0;
    let mergeRate = 0;
    let sum_capInc = 0;
    let sum_freeCap = 0;
    scwin.unformat($c.util.getComponent("ipt_capitalstock"));
    scwin.unformat($c.util.getComponent("ipt_parval"));
    scwin.unformat($c.util.getComponent("ipt_sumCapInc"));
    scwin.unformat($c.util.getComponent("ipt_sumFreeCap"));
    if (($c.util.getComponent('ipt_capitalstock').getValue() == null ? '' : String($c.util.getComponent('ipt_capitalstock').getValue())) !== '' && $c.util.getComponent('ipt_capitalstock').getValue() != null) {
        capital = parseInt($c.util.getComponent('ipt_capitalstock').getValue());
    }
    if (($c.util.getComponent('ipt_parval').getValue() == null ? '' : String($c.util.getComponent('ipt_parval').getValue())) !== '' && $c.util.getComponent('ipt_parval').getValue() != null) {
        parval = parseInt($c.util.getComponent('ipt_parval').getValue());
    }
    if (($c.util.getComponent('ipt_sumCapInc').getValue() == null ? '' : String($c.util.getComponent('ipt_sumCapInc').getValue())) !== '' && $c.util.getComponent('ipt_sumCapInc').getValue() != null) {
        sum_capInc = parseInt($c.util.getComponent('ipt_sumCapInc').getValue());
    }
    if (($c.util.getComponent('ipt_sumFreeCap').getValue() == null ? '' : String($c.util.getComponent('ipt_sumFreeCap').getValue())) !== '' && $c.util.getComponent('ipt_sumFreeCap').getValue() != null) {
        sum_freeCap = parseInt($c.util.getComponent('ipt_sumFreeCap').getValue());
    }
    if (sum_capInc - capital > 0) {
        $c.util.getComponent('ipt_safeGuardDepCap1').setValue(sum_capInc - capital);
    } else {
        $c.util.getComponent('ipt_safeGuardDepCap1').setValue(0);
    }
    if (sum_freeCap - capital > 0) {
        $c.util.getComponent('ipt_safeGuardDepCap2').setValue(sum_freeCap - capital);
    } else {
        $c.util.getComponent('ipt_safeGuardDepCap2').setValue(0);
    }
    const safeGuardDepCap_1 = $c.util.getComponent('ipt_safeGuardDepCap1').getValue();
    const safeGuardDepCap_2 = $c.util.getComponent('ipt_safeGuardDepCap2').getValue();
    $c.util.getComponent('ipt_safeGuardDepBeIssue1').setValue(safeGuardDepCap_1 / parval);
    $c.util.getComponent('ipt_safeGuardDepBeIssue2').setValue(safeGuardDepCap_2 / parval);
    const safeGuardDepBeIssue_1 = $c.util.getComponent('ipt_safeGuardDepBeIssue1').getValue();
    const safeGuardDepBeIssue_2 = $c.util.getComponent('ipt_safeGuardDepBeIssue2').getValue();
    mergeRate = $c.util.getComponent('ipt_mergeRate').getValue();
    $c.util.getComponent('ipt_safeGuardDepAftIssue1').setValue(Math.round(safeGuardDepBeIssue_1 * mergeRate));
    $c.util.getComponent('ipt_safeGuardDepAftIssue2').setValue(Math.round(safeGuardDepBeIssue_2 * mergeRate));
    const safeGuardDepAftIssue_1 = $c.util.getComponent('ipt_safeGuardDepAftIssue1').getValue();
    const safeGuardDepAftIssue_2 = $c.util.getComponent('ipt_safeGuardDepAftIssue2').getValue();
    await scwin.numFormat($c.util.getComponent("ipt_capitalstock"));
    await scwin.numFormat($c.util.getComponent("ipt_parval"));
    await scwin.numFormat($c.util.getComponent("ipt_sumCapInc"));
    await scwin.numFormat($c.util.getComponent("ipt_sumFreeCap"));
    await scwin.numFormat($c.util.getComponent("ipt_safeGuardDepCap1"));
    await scwin.numFormat2($c.util.getComponent("ipt_safeGuardDepBeIssue1"));
    await scwin.numFormat2($c.util.getComponent("ipt_safeGuardDepAftIssue1"));
    await scwin.numFormat($c.util.getComponent("ipt_safeGuardDepCap2"));
    await scwin.numFormat2($c.util.getComponent("ipt_safeGuardDepBeIssue2"));
    await scwin.numFormat2($c.util.getComponent("ipt_safeGuardDepAftIssue2"));
    /* sdd-asis-lifecycle:end */
};
